using System.Text.Json;
using Dip.Application.Abstractions.Persistence;
using Dip.Application.Abstractions.Time;
using Dip.Domain.Entities;

namespace Dip.Application.Features.Triage;
public sealed record RegressionTriageRequest(Guid ProjectId,Guid IncidentId,string? SuspectedSubsystem=null,IReadOnlyList<string>? SuspectedFiles=null,string? SuggestedOwner=null);
public sealed record RegressionTriageDto(Guid Id,Guid IncidentId,string? SuspectedCommit,string? SuspectedSubsystem,IReadOnlyList<string> SuspectedFiles,string? SuggestedOwner,decimal Confidence,IReadOnlyList<Guid> EvidenceIds,string Explanation,DateTimeOffset CreatedAtUtc);

public sealed class RegressionTriageService
{
    private readonly IIncidentRepository _incidents;private readonly IRegressionTriageRepository _repo;private readonly IEvidenceRepository _evidence;private readonly IChangeRiskRepository _risk;private readonly IUnitOfWork _uow;private readonly ISystemClock _clock;
    public RegressionTriageService(IIncidentRepository incidents,IRegressionTriageRepository repo,IEvidenceRepository evidence,IChangeRiskRepository risk,IUnitOfWork uow,ISystemClock clock){_incidents=incidents;_repo=repo;_evidence=evidence;_risk=risk;_uow=uow;_clock=clock;}
    public async Task<RegressionTriageDto> TriageAsync(RegressionTriageRequest r,CancellationToken ct)
    {
        var incident=await _incidents.GetAsync(r.IncidentId,ct)??throw new KeyNotFoundException($"Incident {r.IncidentId} was not found.");if(incident.ProjectId!=r.ProjectId)throw new InvalidOperationException("Incident does not belong to the requested project.");
        var events=await _incidents.ListEventsAsync(incident.Id,ct);var occurrences=await _incidents.ListOccurrencesAsync(incident.Id,50,ct);var evidence=(await _evidence.ListForProjectAsync(r.ProjectId,_clock.UtcNow.AddDays(-90),ct)).Where(x=>x.SubjectKey==incident.SubjectKey).OrderByDescending(x=>x.ObservedAtUtc).Take(20).ToArray();var risk=await _risk.GetLatestAsync(r.ProjectId,incident.SuspectedRegressionCommit,ct);
        decimal confidence=25m;var reasons=new List<string>();if(!string.IsNullOrWhiteSpace(incident.SuspectedRegressionCommit)){confidence+=25;reasons.Add("Regression-origin evidence identifies a suspected commit.");}if(incident.ReproducedCount>0){confidence+=20;reasons.Add($"Incident reproduced {incident.ReproducedCount} time(s).");}if(!string.IsNullOrWhiteSpace(incident.RootCauseSummary)){confidence+=15;reasons.Add("Evidence-grounded root-cause context exists.");}if(events.Any(x=>x.Type==Dip.Domain.Enums.IncidentEventType.Symbolicated)){confidence+=10;reasons.Add("A symbolicated stack is attached.");}if(risk is not null){confidence+=Math.Min(5m,risk.RiskScore/20m);reasons.Add($"Latest deterministic change-risk score is {risk.RiskScore:0.#}/100.");}
        confidence=Math.Clamp(confidence,0m,100m);var supplied=(r.SuspectedFiles??Array.Empty<string>()).Where(x=>!string.IsNullOrWhiteSpace(x));var observed=occurrences.SelectMany(ExtractFiles);var files=supplied.Concat(observed).Distinct(StringComparer.OrdinalIgnoreCase).Take(20).ToArray();var subsystem=string.IsNullOrWhiteSpace(r.SuspectedSubsystem)?InferSubsystem(files,incident.SubjectKey):r.SuspectedSubsystem;var explanation=reasons.Count==0?"Insufficient evidence exists to rank a regression cause with confidence.":string.Join(" ",reasons);var entity=new RegressionTriage(Guid.NewGuid(),r.ProjectId,r.IncidentId,incident.SuspectedRegressionCommit,subsystem,JsonSerializer.Serialize(files),r.SuggestedOwner,confidence,JsonSerializer.Serialize(evidence.Select(x=>x.Id)),explanation,_clock.UtcNow);await _repo.AddAsync(entity,ct);await _uow.SaveChangesAsync(ct);return Map(entity);
    }
    public async Task<RegressionTriageDto?> GetLatestAsync(Guid incidentId,CancellationToken ct){var x=await _repo.GetLatestForIncidentAsync(incidentId,ct);return x is null?null:Map(x);}
    private static IEnumerable<string> ExtractFiles(IncidentOccurrence occurrence){if(string.IsNullOrWhiteSpace(occurrence.DetailJson))yield break;JsonDocument? doc=null;try{doc=JsonDocument.Parse(occurrence.DetailJson);var root=doc.RootElement;if(root.TryGetProperty("FilePath",out var p)||root.TryGetProperty("filePath",out p)){var value=p.GetString();if(!string.IsNullOrWhiteSpace(value))yield return value;}}finally{doc?.Dispose();}}
    private static string InferSubsystem(IReadOnlyList<string> files,string subjectKey){var text=(string.Join("|",files)+"|"+subjectKey).ToLowerInvariant();if(text.Contains("render")||text.Contains("shader")||text.Contains("gpu"))return "Rendering";if(text.Contains("network")||text.Contains("server")||text.Contains("socket"))return "Networking";if(text.Contains("audio")||text.Contains("sound"))return "Audio";if(text.Contains("ui")||text.Contains("hud"))return "UI";if(text.Contains("asset")||text.Contains("content"))return "Assets/Content";if(text.Contains("database")||text.Contains("migration")||text.Contains("persistence"))return "Persistence";return "Unclassified";}
    private static RegressionTriageDto Map(RegressionTriage x)=>new(x.Id,x.IncidentId,x.SuspectedCommit,x.SuspectedSubsystem,JsonSerializer.Deserialize<string[]>(x.SuspectedFilesJson)??[],x.SuggestedOwner,x.Confidence,JsonSerializer.Deserialize<Guid[]>(x.EvidenceIdsJson)??[],x.Explanation,x.CreatedAtUtc);
}
